import{_ as a,a as t,c as n,ac as i}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第三册：培养技能 · Lesson 10 The loss of the Titanic","description":"学习 过去反事实条件句，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第三册：培养技能 · Lesson 10 The loss of the Titanic","description":"学习 过去反事实条件句，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第3册课时","summary":"学习 过去反事实条件句，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · Lesson 9 Flying cats","link":"/life/english/new-concept/book-3/unit-01/lesson-009"},"next":{"text":"第三册：培养技能 · Lesson 11 Not guilty","link":"/life/english/new-concept/book-3/unit-01/lesson-011"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · Lesson 9 Flying cats","link":"/life/english/new-concept/book-3/unit-01/lesson-009"},"next":{"text":"第三册：培养技能 · Lesson 11 Not guilty","link":"/life/english/new-concept/book-3/unit-01/lesson-011"}},"headers":[],"relativePath":"life/english/new-concept/book-3/unit-01/lesson-010.md","filePath":"life/english/new-concept/book-3/unit-01/lesson-010.md"}'),o={name:"life/english/new-concept/book-3/unit-01/lesson-010.md"};function l(r,e,s,h,d,c){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="第三册-培养技能-·-lesson-10-the-loss-of-the-titanic" tabindex="-1">第三册：培养技能 · Lesson 10 The loss of the Titanic <a class="header-anchor" href="#第三册-培养技能-·-lesson-10-the-loss-of-the-titanic" aria-label="Permalink to &quot;第三册：培养技能 · Lesson 10 The loss of the Titanic&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-3/contents">本册目录</a> · <a href="/life/english/new-concept/book-3/unit-01/overview">单元 1</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>以航行事故叙事为背景，学习说明过去原本有可能避免的结果。重点是把真实发生的事情与事后的假设分开，不把假设当作已证实的历史因果。通过第三条件句练习描述未实现的过去条件，并用谨慎语言评价信息和决策的作用。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>voyage</td><td>/ˈvɔɪɪdʒ/</td><td>n.</td><td>航行</td><td>a long voyage</td></tr><tr><td>collision</td><td>/kəˈlɪʒən/</td><td>n.</td><td>碰撞</td><td>avoid a collision</td></tr><tr><td>warning</td><td>/ˈwɔːnɪŋ/</td><td>n.</td><td>警告</td><td>receive a warning</td></tr><tr><td>rescue</td><td>/ˈreskjuː/</td><td>v.</td><td>营救</td><td>rescue passengers</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>on board — 在船或飞机上</li><li>in time — 来得及，在所需时间之前</li></ul><h2 id="语法讲解-过去反事实条件句" tabindex="-1">语法讲解：过去反事实条件句 <a class="header-anchor" href="#语法讲解-过去反事实条件句" aria-label="Permalink to &quot;语法讲解：过去反事实条件句&quot;">​</a></h2><p>典型结构为 if 加 had 加过去分词，主句用 would have 加过去分词，表示与已知过去事实相反的假设。主句也可用 might have 或 could have，分别突出可能性或能力条件，不能一律译成必然结果。if 从句通常不写 would have。反事实句只展示说话者设想的另一种结果，并不自动证明现实事件只有一个原因；讨论事故时尤其要区分可证实事实、合理推断和条件性评价。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>If the crew had received the warning earlier, they might have changed course.</p></blockquote><p>如果船员更早收到警告，他们也许就会改变航向。</p><p>had received 假设过去条件，might have changed 表示可能而非必然的不同结果。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>If they would have heard the alarm 不符合此处标准反事实条件结构，应写 If they had heard the alarm。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>把 had checked 与 could have replaced 连贯朗读；听自己的录音是否保留 checked 和 replaced 的词尾，以免时态线索丢失。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>We noticed the damaged oar after departure. If we had checked it at the dock, we could have replaced it. Next time, we will inspect all the equipment first.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>为一次虚构划船延误写三句回顾，包含事实、假设和改进。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>过去事实与反事实分句分开，最后一句给出未来可执行的改进。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>例句断言改变航向一定能发生吗？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 没有。</p><p><strong>解析：</strong> might 表示不确定的可能结果。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>填空：If we had left earlier, we ___ have arrived before dark.（would/will）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> would</p><p><strong>解析：</strong> 过去反事实主句用 would have。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>改正：They might have change course.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> They might have changed course.</p><p><strong>解析：</strong> have 后需要过去分词。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：过去反事实条件句。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-3/unit-01/grammar">单元语法</a> · <a href="/life/english/new-concept/book-3/unit-01/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-3/unit-01/review">单元自测</a></p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-009">上一课</a> · <a href="/life/english/new-concept/book-3/unit-01/overview">单元目录</a> · <a href="/life/english/new-concept/book-3/unit-01/lesson-011">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const g=a(o,[["render",l]]);export{u as __pageData,g as default};
